import {BELL_MODEL,BELL_CARDS,BELL_PAGES,BELL_RESPONSES,BELL_SUPPORT,bellCardById,bellNoteById,bellPairById} from './bell-studio-content.mjs';
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const keys=(x,required,optional=[])=>object(x)&&required.every(k=>Object.hasOwn(x,k))&&Object.keys(x).every(k=>required.includes(k)||optional.includes(k));
const clone=x=>structuredClone(x);
function same(a,b){if(a===b)return true;if(Array.isArray(a)||Array.isArray(b))return Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&Object.keys(a).length===a.length&&Object.keys(b).length===b.length&&Array.from(a).every((v,i)=>same(v,b[i]));return object(a)&&object(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&same(a[k],b[k]));}
// Display copy may change; saved rules, tone models, sequences and outcomes must still agree.
const wording=['title','purpose','request','notice','volumeCue','idea','diagramNotice','label'];
const semantic=x=>x==null?x:JSON.parse(JSON.stringify(x,(k,v)=>wording.includes(k)&&typeof v==='string'?'':v));
const sameContent=(a,b)=>same(semantic(a),semantic(b));
export const validBellSequence=s=>Array.isArray(s)&&s.length<=8&&Object.keys(s).length===s.length&&Array.from(s).every(id=>typeof id==='string'&&bellNoteById(id));
const isTone=id=>!!bellNoteById(id)&&id!=='rest';
const index=(i,s)=>i===null||Number.isSafeInteger(i)&&i>=0&&i<s.length;
const supportValid=s=>object(s)&&s.visual===true&&Object.entries(s).every(([k,v])=>BELL_SUPPORT.includes(k)&&v===true);
export function bellArrangementAssessment(card,sequence){
 const c=typeof card==='string'?bellCardById(card):card;if(!c||!sameContent(c,bellCardById(c.id))||!validBellSequence(sequence))return null;
 const allTone=sequence.every(isTone),items=[],add=(id,label,match)=>items.push({id,label,match});
 if(c.rule==='two-pairs'){add('length','Five slots',sequence.length===5);add('first-pair','The first two slots are matching tones',sequence.length>=2&&isTone(sequence[0])&&sequence[0]===sequence[1]);add('rest','The middle slot is a rest',sequence[2]==='rest');add('last-pair','The final two slots are matching tones',sequence.length===5&&isTone(sequence[3])&&sequence[3]===sequence[4]);}
 else if(c.rule==='finish-higher'){add('length','Three slots',sequence.length===3);add('tones','Every slot is a sounding note',sequence.length>0&&allTone);add('higher','The final tone is set higher than the first',sequence.length>=2&&isTone(sequence[0])&&isTone(sequence.at(-1))&&bellNoteById(sequence.at(-1)).frequency>bellNoteById(sequence[0]).frequency);}
 else if(c.rule==='repeat-three'){add('length','Six slots',sequence.length===6);add('tones','Every slot is a sounding note',sequence.length>0&&allTone);add('repeat','The last three repeat the first three in order',sequence.length===6&&sequence.slice(0,3).every((id,i)=>id===sequence[i+3]));}
 else{add('length','One to eight slots',sequence.length>=1&&sequence.length<=8);add('tone','At least one sounding note',sequence.some(isTone));}
 return {items,matches:items.every(x=>x.match)};
}
export function bellComparisonAssessment(pair,response){const p=typeof pair==='string'?bellPairById(pair):pair;if(!p||!sameContent(p,bellPairById(p.id))||!BELL_RESPONSES.includes(response))return null;const [a,b]=p.sequence.map(id=>bellNoteById(id).frequency),relation=b>a?'higher':b<a?'lower':'same';return {firstFrequency:a,secondFrequency:b,relation,response,match:response==='not-sure'?null:response===relation};}
export function bellPlaybackPlan(sequence){if(!validBellSequence(sequence))return null;return {modelId:BELL_MODEL.id,sequence:[...sequence],duration:sequence.length*BELL_MODEL.slotSeconds,hasSound:sequence.some(isTone),slots:sequence.map((id,i)=>({index:i,id,frequency:bellNoteById(id).frequency,start:i*.5,duration:.5,toneSeconds:id==='rest'?0:.35}))};}
export function bellChanges(before,current){if(!validBellSequence(before)||!validBellSequence(current))return null;return {beforeLength:before.length,currentLength:current.length,positions:Array.from({length:Math.max(before.length,current.length)},(_,i)=>({position:i+1,before:before[i]??null,current:current[i]??null})).filter(p=>p.before!==p.current)};}
function versionValid(c,v){return keys(v,['source','sequence','support','familiar','practice','visual'])&&sameContent(v.source,c)&&validBellSequence(v.sequence)&&supportValid(v.support)&&typeof v.familiar==='boolean'&&v.practice===true&&v.visual===true;}
function checkValid(c,s){
 if(!object(s)||!['arrangement','comparison'].includes(s.kind)||!keys(s,['kind','source','support','familiar','practice','visual','assessment'],s.kind==='arrangement'?['sequence']:['pair','response'])||!sameContent(s.source,c)||!supportValid(s.support)||typeof s.familiar!=='boolean'||s.practice!==true||s.visual!==true)return false;
 return s.kind==='arrangement'?validBellSequence(s.sequence)&&sameContent(s.assessment,bellArrangementAssessment(c,s.sequence)):sameContent(s.pair,bellPairById(s.pair?.id))&&BELL_RESPONSES.includes(s.response)&&same(s.assessment,bellComparisonAssessment(s.pair,s.response));
}
function keptValid(c,k){return keys(k,['source','sequence','before','support','familiar','practice','visual','assessment'],['latestArrangement','latestComparison'])&&versionValid(c,{source:k.source,sequence:k.sequence,support:k.support,familiar:k.familiar,practice:k.practice,visual:k.visual})&&(k.before===null||versionValid(c,k.before))&&sameContent(k.assessment,bellArrangementAssessment(c,k.sequence))&&(!Object.hasOwn(k,'latestArrangement')||k.latestArrangement?.kind==='arrangement'&&checkValid(c,k.latestArrangement))&&(!Object.hasOwn(k,'latestComparison')||k.latestComparison?.kind==='comparison'&&checkValid(c,k.latestComparison));}
const latest=(w,kind)=>w.checks.findLast(x=>x.kind===kind)||null;
function workValid(c,w){
 if(!keys(w,['source','sequence','selected','inspect','before','pairId','response','feedback','support','familiar','checks','kept'])||!sameContent(w.source,c)||!validBellSequence(w.sequence)||!index(w.selected,w.sequence)||!index(w.inspect,w.sequence)||!(w.before===null||versionValid(c,w.before))||!bellPairById(w.pairId)||!(w.response===null||BELL_RESPONSES.includes(w.response))||!keys(w.feedback,['arrangement','comparison'])||typeof w.feedback.arrangement!=='boolean'||typeof w.feedback.comparison!=='boolean'||!supportValid(w.support)||typeof w.familiar!=='boolean'||!Array.isArray(w.checks)||w.checks.length>24||Object.keys(w.checks).length!==w.checks.length||!w.checks.every(s=>checkValid(c,s))||!(w.kept===null||keptValid(c,w.kept)))return false;
 const a=latest(w,'arrangement'),p=latest(w,'comparison');return (!w.feedback.arrangement||a&&same(a.sequence,w.sequence))&&(!w.feedback.comparison||p&&p.pair.id===w.pairId&&p.response===w.response);
}
const fresh=()=>({version:1,currentCard:null,page:'choose',cards:{}});
function valid(r){return keys(r,['version','currentCard','page','cards'],['recovered'])&&r.version===1&&BELL_PAGES.includes(r.page)&&object(r.cards)&&Object.keys(r.cards).length<=4&&Object.entries(r.cards).every(([id,w])=>{const c=bellCardById(id);return c&&workValid(c,w);})&&(r.currentCard===null||bellCardById(r.currentCard)&&Object.hasOwn(r.cards,r.currentCard))&&(r.page==='choose'||r.currentCard!==null);}
export function bellState(state){return state.bellStudio===undefined?fresh():valid(state.bellStudio)?state.bellStudio:null;}
export function ensureBellStudio(state){if(state.bellStudio===undefined)state.bellStudio=fresh();return bellState(state);}
export function recoverBellStudio(state){if(state.bellStudio===undefined||bellState(state))return false;const original=state.bellStudio;state.bellStudio={...fresh(),recovered:original};return true;}
const work=r=>r.currentCard?r.cards[r.currentCard]:null;
function change(state,fn){const r=bellState(state);if(!r)return false;const next=clone(r),result=fn(next);if(result===false||!valid(next))return false;state.bellStudio=next;return result??true;}
const newWork=c=>({source:clone(c),sequence:[],selected:null,inspect:null,before:null,pairId:'rise',response:null,feedback:{arrangement:false,comparison:false},support:{visual:true},familiar:false,checks:[],kept:null});
export function chooseBellCard(state,id){const c=bellCardById(id);if(!c)return false;return change(state,r=>{if(!r.cards[id])r.cards[id]=newWork(c);else if(id!==r.currentCard)r.cards[id].familiar=true;r.currentCard=id;r.page='make';});}
export function nextBellCard(state){const r=bellState(state);return r?chooseBellCard(state,BELL_CARDS[(BELL_CARDS.findIndex(c=>c.id===r.currentCard)+1)%4].id):false;}
export function setBellPage(state,page){if(!BELL_PAGES.includes(page))return false;return change(state,r=>{if(page!=='choose'&&!work(r))return false;r.page=page;});}
function edited(w){w.support.editing=true;w.feedback.arrangement=false;w.inspect=null;}
export function appendBellSlot(state,id){if(!bellNoteById(id))return false;return change(state,r=>{const w=work(r);if(!w||w.sequence.length===8)return false;w.sequence.push(id);w.selected=w.sequence.length-1;edited(w);});}
export function selectBellSlot(state,i){return change(state,r=>{const w=work(r);if(!w||!index(i,w.sequence))return false;w.selected=i;});}
export function replaceBellSlot(state,id){if(!bellNoteById(id))return false;return change(state,r=>{const w=work(r);if(!w||w.selected===null||w.sequence[w.selected]===id)return false;w.sequence[w.selected]=id;edited(w);});}
export function moveBellSlot(state,delta){if(![-1,1].includes(delta))return false;return change(state,r=>{const w=work(r),i=w?.selected;if(!w||i===null||!index(i+delta,w.sequence))return false;[w.sequence[i],w.sequence[i+delta]]=[w.sequence[i+delta],w.sequence[i]];w.selected=i+delta;edited(w);});}
export function removeBellSlot(state){return change(state,r=>{const w=work(r);if(!w||w.selected===null)return false;w.sequence.splice(w.selected,1);w.selected=w.sequence.length?Math.min(w.selected,w.sequence.length-1):null;edited(w);});}
export function clearBellSequence(state){return change(state,r=>{const w=work(r);if(!w||!w.sequence.length)return false;w.sequence=[];w.selected=null;edited(w);});}
export function inspectBellSlot(state,delta){if(![-1,1].includes(delta))return false;return change(state,r=>{const w=work(r);if(!w||!w.sequence.length)return false;w.inspect=Math.max(0,Math.min(w.sequence.length-1,(w.inspect??(delta===1?-1:w.sequence.length))+delta));w.support.visualInspection=true;});}
const version=w=>({source:clone(w.source),sequence:[...w.sequence],support:clone(w.support),familiar:w.familiar,practice:true,visual:true});
export function saveBellBefore(state){return change(state,r=>{const w=work(r);if(!w)return false;w.before=version(w);return clone(w.before);});}
export function chooseBellPair(state,id){if(!bellPairById(id))return false;return change(state,r=>{const w=work(r);if(!w)return false;w.pairId=id;w.response=null;w.feedback.comparison=false;});}
export function setBellComparisonResponse(state,response){if(response!==null&&!BELL_RESPONSES.includes(response))return false;return change(state,r=>{const w=work(r);if(!w)return false;w.response=response;w.feedback.comparison=false;});}
export function useBellSupport(state,kind){if(!BELL_SUPPORT.includes(kind)||['visual','editing','arrangementFeedback','comparisonFeedback'].includes(kind))return false;return change(state,r=>{const w=work(r);if(!w)return false;w.support[kind]=true;});}
function push(w,s){w.checks.push(s);while(w.checks.length>24){const i=w.checks.findIndex((old,k)=>w.checks.slice(k+1).some(n=>n.kind===old.kind));w.checks.splice(i,1);}}
function record(state,kind){return change(state,r=>{const w=work(r);if(!w||kind==='comparison'&&w.response===null)return false;const s={kind,source:clone(w.source),...(kind==='arrangement'?{sequence:[...w.sequence]}:{pair:clone(bellPairById(w.pairId)),response:w.response}),assessment:kind==='arrangement'?bellArrangementAssessment(w.source,w.sequence):bellComparisonAssessment(w.pairId,w.response),support:clone(w.support),familiar:w.familiar||w.checks.some(old=>old.kind===kind&&(kind!=='comparison'||old.pair.id===w.pairId)),practice:true,visual:true};push(w,s);w.support[kind==='arrangement'?'arrangementFeedback':'comparisonFeedback']=true;w.feedback[kind]=true;return clone(s);});}
export const checkBellArrangement=state=>record(state,'arrangement');
export const checkBellComparison=state=>record(state,'comparison');
export function keepBellCall(state){return change(state,r=>{const w=work(r);if(!w)return false;w.kept={...version(w),before:w.before===null?null:clone(w.before),assessment:bellArrangementAssessment(w.source,w.sequence)};for(const kind of ['arrangement','comparison']){const s=latest(w,kind);if(s)w.kept[kind==='arrangement'?'latestArrangement':'latestComparison']=clone(s);}return clone(w.kept);});}
export function bellArrangementFeedback(snapshot){if(!snapshot||snapshot.kind!=='arrangement')return '';return snapshot.assessment.matches?'This arrangement fits the pictured request. A listener can help you decide how it works as a call.':'Some parts of the pictured request are still different. You can change the call or keep this draft; it is not a judgement about your music.';}
export function bellComparisonFeedback(snapshot){if(!snapshot||snapshot.kind!=='comparison')return '';return `In this computer pair, the second tone is set ${snapshot.assessment.relation==='same'?'the same':snapshot.assessment.relation}.${snapshot.response==='not-sure'?' Not sure is a useful place to explore from.':''} The model comparison does not tell us what someone heard.`;}
export function bellView(state){const r=bellState(state);if(!r)return null;const w=work(r);if(!w)return {card:null,work:null,page:r.page};const a=latest(w,'arrangement'),p=latest(w,'comparison');return {card:bellCardById(r.currentCard),work:w,page:r.page,sequence:w.sequence,selected:w.selected,inspected:w.inspect===null?null:{index:w.inspect,id:w.sequence[w.inspect]},before:w.before,changes:w.before?bellChanges(w.before.sequence,w.sequence):null,pair:bellPairById(w.pairId),response:w.response,assessment:bellArrangementAssessment(w.source,w.sequence),latestArrangement:a,latestComparison:p,arrangementFeedback:w.feedback.arrangement?bellArrangementFeedback(a):'',comparisonFeedback:w.feedback.comparison?bellComparisonFeedback(p):'',priorArrangement:a&&!w.feedback.arrangement?a:null,priorComparison:p&&!w.feedback.comparison?p:null,actions:{append:w.sequence.length<8,remove:w.selected!==null,moveLeft:w.selected!==null&&w.selected>0,moveRight:w.selected!==null&&w.selected<w.sequence.length-1,play:w.sequence.length>0,inspect:w.sequence.length>0,checkComparison:w.response!==null}};}
